<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
const sections=[{id:'intro',title:'Introduction',body:'Fictitious overview of the local example.'},{id:'details',title:'Details',body:'Scroll within this panel to update the active section.'},{id:'summary',title:'Summary',body:'The active indicator reflects visibility, not task completion.'}]
const root=ref<HTMLElement>(),active=ref('intro'),supported=ref(true)
let observer:IntersectionObserver|undefined
const ratios=new Map<string,number>()
function choose(id:string){const target=root.value?.querySelector<HTMLElement>(`#scrollspy-guide-${id}`);if(target&&root.value)root.value.scrollTo({top:target.offsetTop,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
onMounted(()=>{if(!('IntersectionObserver'in window)){supported.value=false;return}observer=new IntersectionObserver(entries=>{entries.forEach(entry=>ratios.set(entry.target.id.replace('scrollspy-guide-',''),entry.isIntersecting?entry.intersectionRatio:0));const best=sections.reduce((a,b)=>(ratios.get(b.id)||0)>(ratios.get(a.id)||0)?b:a);if((ratios.get(best.id)||0)>0)active.value=best.id},{root:root.value,threshold:[0,.25,.5,.75,1]});root.value?.querySelectorAll('section').forEach(node=>observer?.observe(node))})
onBeforeUnmount(()=>{observer?.disconnect();ratios.clear()})
</script>
<template><section class="scrollspy-usage" aria-label="Scrollspy demonstration"><p>Fictitious local sections. Scroll the inner panel, not just the page.</p><nav aria-label="Sample section navigation"><button v-for="section in sections" :key="section.id" type="button" :aria-current="active===section.id?'location':undefined" :aria-controls="`scrollspy-guide-${section.id}`" @click="choose(section.id)">{{section.title}}</button></nav><p>Active sample section: <strong>{{sections.find(x=>x.id===active)?.title}}</strong></p><p v-if="!supported" role="status">Automatic tracking is unavailable in this browser. The buttons still scroll to each section.</p><div ref="root" class="scroll-panel" role="region" aria-label="Scrollable sample document" tabindex="0"><section v-for="section in sections" :id="`scrollspy-guide-${section.id}`" :key="section.id"><h3>{{section.title}}</h3><p>{{section.body}}</p><p>This is sample explanatory text, not a fetched document or a real progress record.</p></section></div><p>Tracking chooses the section with the largest observed visible fraction; ties keep document order. Clicking scrolls only and does not set active state directly.</p></section></template>
<style scoped>
.scrollspy-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}nav{display:flex;flex-wrap:wrap;gap:12px}button{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft);transition:background 140ms ease-out}button[aria-current=location]{background:var(--vp-c-brand-soft);border-color:var(--vp-c-brand-1);text-decoration:underline}.scroll-panel{position:relative;height:300px;overflow:auto;border:1px solid var(--vp-c-divider);border-radius:8px;overscroll-behavior:contain}.scroll-panel section{box-sizing:border-box;min-height:270px;padding:20px;border-bottom:1px solid var(--vp-c-divider)}.scroll-panel h3{margin:0}.scroll-panel p{overflow-wrap:anywhere}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@media(prefers-reduced-motion:reduce){button{transition:none}}
</style>
